      const parts = [item(d.name, () => QuickPick.open("@"))];
      for (const s of chain.filter(Boolean)) parts.push(document.createTextNode(" › "), item(s.label, () => Views.revealLine(d, s.line)));
      dom.replaceChildren(...parts);
